export function getSkillDetailCopy(locale: Locale): ResolvedSkillDetailCopy {
  return {
    ...en,
    ...extraEn,
    ...componentEn,
    ...(copies[locale] || en),
    ...(extraCopies[locale] || {}),
    ...(detailUiOverrides[locale] || {}),
    ...(componentCopies[locale] || {}),
    // This label appears both as authored UI copy and as a scoring signal.
    // Keep the two surfaces in sync instead of allowing the scorecard to
    // localize while the technical-details grid falls back to English.
    license: systemValueMaps[locale]?.license || extraEn.license,
  }
}

export function formatSkillDetailCopy(
  locale: Locale,
  key: SkillDetailCopyKey,
  values?: CopyValues
) {
  const text = getSkillDetailCopy(locale)[key]
  if (!values) return text
  return text.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? ''))
}

