function formatRepoActivity(locale: Locale, stars: string, forks: string, hasIssueNote: boolean) {
  const issueNote = hasIssueNote
    ? {
        en: 'issue activity unavailable in current metadata',
        zh: '当前元数据中没有议题活跃度信息',
        ja: '現在のメタデータでは Issue 活動を利用できません',
        ko: '현재 메타데이터에서 이슈 활동을 확인할 수 없습니다',
        es: 'la actividad de issues no está disponible en los metadatos actuales',
        de: 'Issue-Aktivität ist in den aktuellen Metadaten nicht verfügbar',
        fr: 'l’activité des issues n’est pas disponible dans les métadonnées actuelles',
        id: 'aktivitas issue tidak tersedia dalam metadata saat ini',
      }[locale]
    : null

  const base = {
    en: `${stars} stars, ${forks} forks`,
    zh: `${stars} 个 Star，${forks} 个 Fork`,
    ja: `スター ${stars}、フォーク ${forks}`,
    ko: `스타 ${stars}, 포크 ${forks}`,
    es: `${stars} estrellas y ${forks} forks`,
    de: `${stars} Stars und ${forks} Forks`,
    fr: `${stars} stars et ${forks} forks`,
    id: `${stars} star dan ${forks} fork`,
  }[locale]

  return issueNote ? `${base}; ${issueNote}` : base
}

function formatAgentSafetyScore(locale: Locale, score: string) {
  return {
    en: `${score}/100 agent safety score`,
    zh: `${score}/100 Agent 安全评分`,
    ja: `Agent 安全スコア ${score}/100`,
    ko: `Agent 안전 점수 ${score}/100`,
    es: `puntuación de seguridad del Agent: ${score}/100`,
    de: `Agent-Sicherheitswert ${score}/100`,
    fr: `score de sécurité Agent : ${score}/100`,
    id: `skor keamanan Agent ${score}/100`,
  }[locale]
}

function formatOutcomeConfidence(locale: Locale, confidence: string, reports: string) {
  return {
    en: `Outcome confidence ${confidence}% from ${reports} report(s)`,
    zh: `基于 ${reports} 份报告的结果置信度为 ${confidence}%`,
    ja: `${reports} 件のレポートに基づく成果信頼度 ${confidence}%`,
    ko: `${reports}건의 보고서 기반 결과 신뢰도 ${confidence}%`,
    es: `confianza de resultados del ${confidence}% a partir de ${reports} informe(s)`,
    de: `Ergebniszuverlässigkeit ${confidence}% aus ${reports} Bericht(en)`,
    fr: `fiabilité des résultats : ${confidence}% sur ${reports} rapport(s)`,
    id: `kepercayaan hasil ${confidence}% dari ${reports} laporan`,
  }[locale]
}

function translateLiteralValue(locale: Locale, value: string) {
  const normalized = value.trim().toLowerCase()
  return systemValueMaps[locale]?.[normalized] ||
    genericValueMaps[locale]?.[normalized] ||
    generatedMessageMaps[locale]?.[normalized] ||
    platformValueMaps[locale]?.[normalized] ||
    runtimeGeneratedValueMaps[locale]?.[normalized]
}

function formatSandboxValidationStep(locale: Locale, task: string) {
  const translatedTask = translateLiteralValue(locale, task) || task
  return {
    en: `Install it in a sandbox agent and run one ${translatedTask} task end to end.`,
    zh: `在沙盒 Agent 中安装它，并端到端完成一次${translatedTask}任务。`,
    ja: `サンドボックスの Agent にインストールし、${translatedTask} タスクを一度最初から最後まで実行します。`,
    ko: `샌드박스 Agent에 설치하고 ${translatedTask} 작업을 처음부터 끝까지 한 번 실행하세요.`,
    es: `Instálalo en un Agent de sandbox y ejecuta una tarea de ${translatedTask} de principio a fin.`,
    de: `Installieren Sie es in einem Sandbox-Agent und führen Sie eine ${translatedTask}-Aufgabe vollständig aus.`,
    fr: `Installez-le dans un Agent en sandbox et exécutez une tâche de ${translatedTask} de bout en bout.`,
    id: `Pasang di Agent sandbox dan jalankan satu tugas ${translatedTask} dari awal hingga akhir.`,
  }[locale]
}

function formatHighRiskPermissionHints(locale: Locale, hints: string) {
  const translatedHints = translateLiteralValue(locale, hints) || hints
  return {
    en: `High-risk permission hints: ${translatedHints}`,
    zh: `高风险权限提示：${translatedHints}`,
    ja: `高リスク権限のヒント: ${translatedHints}`,
    ko: `고위험 권한 힌트: ${translatedHints}`,
    es: `Indicios de permisos de alto riesgo: ${translatedHints}`,
    de: `Hinweise auf Hochrisiko-Berechtigungen: ${translatedHints}`,
    fr: `Indices de permissions à haut risque : ${translatedHints}`,
    id: `Petunjuk izin berisiko tinggi: ${translatedHints}`,
  }[locale]
}

function translatePattern(locale: Locale, value: string) {
  const copy = dynamicPatternCopies[locale]
  const matchers: Array<[RegExp, (match: RegExpMatchArray) => string]> = [
    [/^([\d.,]+[KM]?) stars, ([\d.,]+[KM]?) forks; issue activity unavailable in current metadata$/i, (match) => formatRepoActivity(locale, match[1], match[2], true)],
    [/^([\d.,]+[KM]?) stars, ([\d.,]+[KM]?) forks$/i, (match) => formatRepoActivity(locale, match[1], match[2], false)],
    [/^(\d+)\/100 agent safety score$/i, (match) => formatAgentSafetyScore(locale, match[1])],
    [/^Outcome confidence ([\d.]+)% from ([\d.,]+[KM]?) report\(s\)$/i, (match) => formatOutcomeConfidence(locale, match[1], match[2])],
    [/^Install it in a sandbox agent and run one (.+) task end to end\.$/i, (match) => formatSandboxValidationStep(locale, match[1])],
    [/^High-risk permission hints: (.+)$/i, (match) => formatHighRiskPermissionHints(locale, match[1])],
    [/^Primary pick for (.+)$/i, (match) => copy.primaryPickFor(translateLiteralValue(locale, match[1]) || match[1])],
    [/^(.+) workflows$/i, (match) => copy.workflows(translateLiteralValue(locale, match[1]) || match[1])],
    [/^(.+) teams$/i, (match) => copy.teams(translateLiteralValue(locale, match[1]) || match[1])],
    [/^([\d.,]+[KM]?) GitHub stars$/i, (match) => copy.githubStars(match[1])],
    [/^([\d.,]+[KM]?) OpenAgentSkill engagement events$/i, (match) => copy.engagementEvents(match[1])],
    [/^([\d.]+)\/100 quality profile$/i, (match) => copy.qualityProfile(match[1])],
    [/^(\d+)d since push$/i, (match) => copy.daysSincePush(match[1])],
    [/^(\d+)mo since push$/i, (match) => copy.monthsSincePush(match[1])],
    [/^(\d+)y since push$/i, (match) => copy.yearsSincePush(match[1])],
    [/^(\d+)d ago$/i, (match) => copy.daysAgo(match[1])],
    [/^(\d+)mo ago$/i, (match) => copy.monthsAgo(match[1])],
    [/^(\d+)y ago$/i, (match) => copy.yearsAgo(match[1])],
    [/^(\d+) events$/i, (match) => copy.events(match[1])],
  ]

  for (const [pattern, format] of matchers) {
    const match = value.match(pattern)
    if (match) return format(match)
  }

  return value
}

export function translateSkillDetailValue(locale: Locale, value: string) {
  return translateLiteralValue(locale, value) || translatePattern(locale, value)
}
